using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
namespace PowerShapeBridge {
 internal static class OwnedSurfaceTranslationTests {
  static void Need(bool ok,string why){if(!ok)throw new InvalidOperationException(why);}
  static Dictionary<string,object> Clone(object o){return Program.Json.Deserialize<Dictionary<string,object>>(Program.Json.Serialize(o));}
  internal class Context:OwnedTranslation.IContext,OwnedSelection.IContext,NativeSurfaceSampling.IContext {
   internal Dictionary<string,object> Snapshot,Listing;internal string Fault;internal int Calls;
   public Dictionary<string,object> Observation(){return Clone(Snapshot);}public Dictionary<string,object> Windows(){return Clone(Listing);}public void ConfirmDocument(){}public void Dispose(){}
   public int Composite(int t,int n){Need(t==21,"Wrong surface native type");return 420000000+n;}public int SelectionCount(){return 0;}
   public double[] Bounds(int n){throw new InvalidOperationException("Surface translation requested unavailable bbox");}public void ChangeSelection(OwnedSelectionProgram p){throw new InvalidOperationException("Translation changed selection");}
   public object ModelItems(){return new[]{420000008,420000009};}public object SelectedItems(){throw new InvalidOperationException("Empty count cannot be inferred from null selected items");}
   public object ItemData(object ids){var keys=((int[])ids).Select(i=>i-420000000).ToArray();return new object[]{keys.Select(i=>21).ToArray(),keys,keys.Select(i=>i==8?"Synthetic_21":"Other_21").ToArray(),keys.Select(i=>0).ToArray()};}
   public virtual object SurfacePoints(string name,double ts,double te,int td,double us,double ue,int ud){int n=(td+1)*(ud+1);var p=Enumerable.Range(0,n*3).Select(i=>i+0.33333333333333337).ToArray();var normal=Enumerable.Range(0,n*3).Select(i=>i%3==2?1.0:0.0).ToArray();if(Calls>0){if(name=="Synthetic_21"&&Fault!="wrong_position")for(int i=0;i<n;i++)p[3*i]+=1;if(name=="Other_21"&&Fault=="other_drift")p[0]=0.33333333333333343;if(Fault=="normal_drift")normal[0]=0.01;}return new object[]{Fault=="domain_error"?-3:0,p,normal,Enumerable.Repeat(true,n).ToArray()};}
   public virtual int Translate(int id,double[] v){Need(id==420000008&&v.SequenceEqual(new[]{1.0,0,0}),"Unexpected target/vector");Calls++;if(Fault=="throw_after")throw new IOException("Lost native return");if(Fault=="area_drift")((Dictionary<string,object>)EntitySets.Inventory(Snapshot)[0]["geometry"])["areaRaw"]=99;return Fault=="return_zero"?0:1;}
  }
  internal static int Run(){Need(File.Exists(Path.Combine(Program.Root,".surface-translation-fixture")),"Isolated surface translation fixture marker required; never CAD.");var rows=new List<object>();foreach(string fault in new[]{"control","domain_error","return_zero","throw_after","wrong_position","other_drift","normal_drift","area_drift"}){
   var f=new OwnedOperationPlanTests.Fixture(true,true,true);var c=new Context{Snapshot=Clone(f.Snapshot),Listing=Clone(f.Listing),Fault=fault};var args=OwnedTranslationTests.Handle(f);args["surfaceGrid"]=new Dictionary<string,object>{{"tStart",1},{"tEnd",2},{"tDivisions",2},{"uStart",1},{"uEnd",2},{"uDivisions",3}};var old=OwnedTranslation.Execute(f.Root,Guid.NewGuid().ToString("N"),args,c);Need(Equals(old["state"],"owned_translation_rejected_before_change")&&c.Calls==0,"Old SOLID recipe accepted SURFACE/grid");
   string id=Guid.NewGuid().ToString("N");var e=OwnedTranslation.Execute(f.Root,id,args,c,true);bool success=fault=="control",pre=fault=="domain_error";Need(Equals(e["state"],success?"owned_translation_executed_unverified":pre?"owned_translation_rejected_before_change":"owned_translation_outcome_unknown"),Program.Json.Serialize(e));Need(c.Calls==(pre?0:1),"Callback count differs");if(pre){rows.Add(new{fault,calls=c.Calls});continue;}
   string sha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",id+".json"),e);var replay=OwnedTranslation.Execute(f.Root,Guid.NewGuid().ToString("N"),args,c,true);Need(Equals(replay["state"],"owned_translation_rejected_before_change")&&c.Calls==1,"Replay reached native TranslateItem");DateTime stamp=DateTime.UtcNow;if(fault!="throw_after"){var journal=NativeJournal.ForVerification(f.Root,id,(string)e["planSha256"]);if(stamp<=journal.CommandReturnedUtc)stamp=journal.CommandReturnedUtc.AddTicks(1);}
   var o=c.Observation();o["timestampUtc"]=stamp.ToString("o");string inspect=Guid.NewGuid().ToString("N"),listing=Guid.NewGuid().ToString("N");var w=c.Windows();w["timestampUtc"]=stamp.AddTicks(1).ToString("o");w["state"]="documents_listed_verified";
   var proof=new Dictionary<string,object>{{"executionRequestId",id},{"executionReceiptSha256",sha},{"inspectionRequestId",inspect},{"inspectionSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",inspect+".json"),o)},{"listingRequestId",listing},{"listingSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",listing+".json"),w)},{"windowNumber",1},{"modelId",9},{"expiresUtc",DateTime.UtcNow.AddSeconds(150).ToString("o")}};
   Need(Equals(OwnedTranslation.Verify(f.Root,proof,c)["state"],"owned_translation_verification_rejected"),"Old verifier accepted surface plan");var v=OwnedTranslation.Verify(f.Root,proof,c,true);Need(Equals(v["state"],success?"owned_translation_verified_observed":"owned_translation_verification_rejected"),Program.Json.Serialize(v));Need(File.Exists(OwnedTranslation.FencePath(f.Root,(string)e["copyId"]))!=success&&c.Calls==1,"Unproved fence removed or callback repeated");rows.Add(new{fault,calls=c.Calls,state=v["state"]});
  }Directory.CreateDirectory(Path.Combine(Program.Root,"reports"));NativeJournal.Freeze(Path.Combine(Program.Root,"reports","surface-translation-tests.json"),new{state="passed",rows,cadConnectionAttempted=false});Console.WriteLine("PASS: "+rows.Count+" surface translation lifecycle/measurement controls; no CAD.");return rows.Count;}
 }
}
